sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Extra guard in case someone removes the BR condition later
    if ((current.vehicle_status + '') !== 'sent_for_servicing')
        return;

    // Need a tracker sys_id and a vehicle reference to proceed
    if (!current.sys_id || !current.vehicle)
        return;

    // 1) Is there already an OPEN servicing ticket for this tracker?
    var existing = new GlideRecord('x_746154_loaner_0_vehicle_servicing');
    existing.addQuery('vehicle_tracker', current.sys_id);   // link back to this tracker
    existing.addQuery('ticket_status', 'open');             // your Q5: field/value
    existing.setLimit(1);
    existing.query();
    if (existing.next()) {
        // An open ticket already exists — do not create another.
        return;
    }

    // 2) Create a new servicing ticket with required mappings
    var svc = new GlideRecord('x_746154_loaner_0_vehicle_servicing');
    svc.initialize();

    // Vehicle Tracker - from which the ticket was opened
    svc.vehicle_tracker = current.sys_id;

    // Vehicle - from the tracker
    svc.vehicle = current.vehicle;                          // your Q6

    // Vehicle Status - In Service
    svc.vehicle_status = 'in_service';                      // your Q7 (stored value)

    // Date sent for Servicing - date when ticket created (your field is a Date)
    var nowGdt = new GlideDateTime();
    svc.date_sent_for_servicing = nowGdt.getDate();         // writes a date-only value

    // Ticket Status - Open
    svc.ticket_status = 'open';                             // your Q5

    svc.insert();


})(current, previous);
